package vn.covie.checkout.application;
import com.fasterxml.jackson.databind.JsonNode; import java.time.*; import java.util.UUID; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.covie.checkout.config.CheckoutProperties; import vn.covie.checkout.model.*; import vn.covie.checkout.persistence.CheckoutSessionRepository; import vn.covie.shared.id.UuidV7Generator; import vn.covie.shared.time.AppClock; import vn.covie.shared.web.*;
@Service public class CheckoutSessionService{private final CheckoutSessionRepository sessions;private final CheckoutTokenGenerator tokens;private final CheckoutTokenHasher hasher;private final CheckoutProperties properties;private final UuidV7Generator ids;private final AppClock clock;public CheckoutSessionService(CheckoutSessionRepository sessions,CheckoutTokenGenerator tokens,CheckoutTokenHasher hasher,CheckoutProperties properties,UuidV7Generator ids,AppClock clock){this.sessions=sessions;this.tokens=tokens;this.hasher=hasher;this.properties=properties;this.ids=ids;this.clock=clock;}@Transactional public CreatedCheckoutSession create(UUID user,CheckoutSourceType type,JsonNode source,Long cartVersion,JsonNode request,JsonNode preview){String raw=tokens.generate();Instant now=clock.now(),expires=now.plus(properties.sessionTtl());UUID id=ids.generate();sessions.save(CheckoutSessionEntity.create(id,hasher.hash(raw),user,type,source,cartVersion,request,preview,expires,now));return new CreatedCheckoutSession(id,raw,expires);}@Transactional public CheckoutSessionEntity lock(String raw,UUID user){var s=sessions.findByTokenHashForUpdate(hasher.hash(raw)).orElseThrow(()->invalid("Checkout session is invalid."));if(!s.getUserId().equals(user))throw invalid("Checkout session is invalid.");if(s.getConsumedAt()!=null)throw new ApiException(ErrorCode.CHECKOUT_SESSION_CONSUMED,HttpStatus.CONFLICT,"Checkout session was consumed.");if(!s.getExpiresAt().isAfter(clock.now()))throw new ApiException(ErrorCode.CHECKOUT_SESSION_EXPIRED,HttpStatus.CONFLICT,"Checkout session expired.");return s;}private static ApiException invalid(String m){return new ApiException(ErrorCode.CHECKOUT_SESSION_INVALID,HttpStatus.CONFLICT,m);}}
